\mathsf{Ctx}_{\mathsf{FC}}
=
\{(\Delta;\Gamma;\Omega):\Delta,\Gamma,\Omega\text{ 如上且三类名称分别互异}\}.

\operatorname{Act}_i(N(b;O;E),v,S)=
\begin{cases}
N(b;O';E)&i=j\ \land\ b=v,\\
N(b;O';\operatorname{Act}_i(E,v,S))&\neg(i=j\land b=v)\ \land\ b\notin FV^j(S),\\
N(d;O';\operatorname{Act}_i(\operatorname{Act}_j(E,b,V_j(d)),v,S))&\neg(i=j\land b=v)\ \land\ b\in FV^j(S).
\end{cases}
